[
  {
    "sys_fairness_reciprocity": "We did identical work side by side until late.",
    "sys_consequence_reasoning": "coworker walks away with nothing for those hours while I pocket $200",
    "pda_harm_regret": "gap would sit on my conscience for a long time.",
    "pda_responsibility": "let one word from me cost someone real money."
  },
  {
    "pd_decision_conflict": "scares me a little because it's all on my say-so.",
    "sys_fairness_reciprocity": "worked just as hard ends up $200 poorer, and nothing about that would be fair.",
    "sys_consequence_reasoning": "the only thing a no would do is take money away from someone.",
    "pda_harm_regret": "I couldn't live easily with that."
  },
  {
    "pda_responsibility": "One sentence from me and my coworker loses out on $200",
    "sys_fairness_reciprocity": "earned the same way I earned mine.",
    "ce_mentalizing_difficulty": "I have no idea what that money would cover for them",
    "pd_harm_distress": "that's part of what bothers me.",
    "sys_consequence_reasoning": "Anything else feels like quietly robbing them."
  },
  {
    "ce_mentalizing_difficulty": "I don't know the organizer's budget",
    "sys_fairness_reciprocity": "the work was equal.",
    "sys_consequence_reasoning": "coworker is out $200 for an evening of real labor",
    "pda_responsibility": "I'd be the reason.",
    "pd_harm_distress": "That weighs on me more than any budget question."
  },
  {
    "sys_fairness_reciprocity": "Equal work, equal thanks.",
    "pd_harm_distress": "Recommending anything less makes my chest tight",
    "sys_consequence_reasoning": "a coworker goes home unpaid for the same late night I got paid for.",
    "pda_responsibility": "it would trace straight back to me."
  },
  {
    "sys_consequence_reasoning": "coworker misses out on $200",
    "pda_responsibility": "because I was wishy-washy.",
    "pda_harm_regret": "I don't want that on me.",
    "sys_fairness_reciprocity": "pay them what you paid me."
  },
  {
    "sys_consequence_reasoning": "Nothing good for me, and a $200 hole for the person who worked beside me.",
    "pda_harm_regret": "I keep turning it over and it doesn't get any less ugly.",
    "sys_fairness_reciprocity": "pay them the same.",
    "pda_practical_counterfactual": "I'd even check back later to make sure it actually went through",
    "pd_harm_distress": "I'd be uneasy if it slipped."
  },
  {
    "sys_fairness_reciprocity": "Two people, same hours, same tasks, and only one gets paid? That lopsidedness",
    "pd_harm_distress": "would bother me every time I saw my coworker at work.",
    "sys_consequence_reasoning": "They'd have lost real money for a job well done",
    "pda_responsibility": "I'd know I had the power to stop it."
  },
  {
    "pd_harm_distress": "the no is the one I dread.",
    "sys_consequence_reasoning": "It hands my coworker a flat loss, $200 gone",
    "sys_fairness_reciprocity": "for work that matched mine hour for hour.",
    "ce_mentalizing_difficulty": "I can't tell that from what I've been told."
  },
  {
    "pd_decision_conflict": "it unsettles me that my recommendation alone decides this",
    "pda_responsibility": "my recommendation alone decides this",
    "sys_consequence_reasoning": "no would mean my coworker takes home nothing after an equal share of the work",
    "sys_fairness_reciprocity": "unfair loss I'd be causing on purpose."
  }
]
